129	        // ─────────────────────────────────────────────────────────────────────
130	        // Main data fetch per server
131	        // ─────────────────────────────────────────────────────────────────────
132	        private static async Task GetOcrDataList(
133	            string connString,
134	            IXLWorksheet wsClient,
135	            IXLWorksheet wsJob,
136	            IXLWorksheet wsFormat,
137	            string serverName,
138	            RowPointers rows)
139	        {
140	            await Task.Run(() =>
141	            {
142	                // ── Step 1: Admin SP ──────────────────────────────────────────
143	                DataSet adminData;
144	                try
145	                {
146	                    adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
147	                }
148	                catch (Exception ex)
149	                {
150	                    Logger.Error(ex, "Admin SP failed for server {0}", serverName);
151	                    return;
152	                }
153	
154	                if (adminData == null || adminData.Tables.Count < 2)
155	                {
156	                    Logger.Warn("Server {0}: No data from admin SP", serverName);
157	                    return;
158	                }
159	
160	                DataTable clientList = adminData.Tables[0]; // → Sheet 1
161	                DataTable serverList = adminData.Tables[1]; // connection details
162	
163	                Logger.Info("Server {0}: Clients={1}, DB rows={2}",
164	                    serverName, clientList.Rows.Count, serverList.Rows.Count);
165	
166	                // ── Sheet 1 ───────────────────────────────────────────────────
167	                AppendDataTable(wsClient, clientList, ref rows.ClientRow);
168	
169	                // ── Step 2: Deduplicate by COMPANY_LICENSE ────────────────────
170	                // Admin SP returns one row per IMP/EXP per company.
171	                // We only need one DB connection per company for client SP calls.
172	                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
173	                var uniqueServers = serverList.AsEnumerable()
174	                    .Where(r => seen.Add(r["COMPANY_LICENSE"].ToString().Trim()))
175	                    .ToList();
176	
177	                Logger.Info("Server {0}: Unique companies after dedup = {1}",
178	                    serverName, uniqueServers.Count);
179	
180	                foreach (DataRow server in uniqueServers)
181	                {
182	                    string workingPeriod = server["WORKING_PERIOD"].ToString();
183	                    string companyLicense = server["COMPANY_LICENSE"].ToString();
184	                    string companyName = server["COMPANY_NAME"].ToString();
185	                    string clientConn = server["CON_STRING"].ToString();
186	
187	                    string enabledDate = ParseDateToYMD(server["ENABLED_ON"].ToString());
188	                    string disabledDate = string.IsNullOrWhiteSpace(
189	                                             server["DISABLED_ON"].ToString())
190	                                         ? ""
191	                                         : ParseDateToYMD(server["DISABLED_ON"].ToString());
192	
193	                    Logger.Info("Server {0}, Company {1} ({2}): calling JOB_COUNT",
194	                        serverName, companyLicense, companyName);
195	
196	                    // ── Sheet 2: JOB_COUNT ────────────────────────────────────
197	                    DataTable jobData = GetClientData(
198	                        clientConn, "JOB_COUNT",
199	                        serverName, workingPeriod, companyLicense,
200	                        companyName, enabledDate, disabledDate);
201	
202	                    Logger.Info("Server {0}, Company {1}: JOB rows={2}",
203	                        serverName, companyLicense, jobData.Rows.Count);
204	
205	                    AppendDataTable(wsJob, jobData, ref rows.JobRow);
206	
207	                    Logger.Info("Server {0}, Company {1}: calling FORMAT_COUNT",
208	                        serverName, companyLicense);
209	
210	                    // ── Sheet 3: FORMAT_COUNT ─────────────────────────────────
211	                    DataTable formatData = GetClientData(
212	                        clientConn, "FORMAT_COUNT",
213	                        serverName, workingPeriod, companyLicense,
214	                        companyName, enabledDate, disabledDate);
215	
216	                    Logger.Info("Server {0}, Company {1}: FORMAT rows={2}",
217	                        serverName, companyLicense, formatData.Rows.Count);
218	
219	                    AppendDataTable(wsFormat, formatData, ref rows.FormatRow);
220	                }
221	            });
222	        }
