224	        // ─────────────────────────────────────────────────────────────────────
225	        // Admin SP — OCR_AI_ENABLED_COUNT (ADMIN_IMPEX DB)
226	        // ─────────────────────────────────────────────────────────────────────
227	        private static DataSet GetAdminData(
228	            string connString, string flag, string serverName)
229	        {
230	            using var con = new SqlConnection(connString);
231	            using var cmd = new SqlCommand("OCR_AI_ENABLED_COUNT", con)
232	            {
233	                CommandType = CommandType.StoredProcedure,
234	                CommandTimeout = 120
235	            };
236	
237	            cmd.Parameters.AddWithValue("@MFLAG", flag);
238	            cmd.Parameters.AddWithValue("@serverName", serverName);
239	
240	            var errParam = new SqlParameter("@ERRORMSG",
241	                System.Data.SqlDbType.NVarChar, -1)
242	            { Direction = ParameterDirection.Output };
243	            cmd.Parameters.Add(errParam);
244	
245	            var adapter = new SqlDataAdapter(cmd);
246	            var ds = new DataSet();
247	            adapter.Fill(ds);
248	
249	            string errMsg = errParam.Value?.ToString();
250	            if (!string.IsNullOrEmpty(errMsg))
251	                Logger.Warn("Admin SP Error [{0}]: {1}", serverName, errMsg);
252	
253	            return ds;
254	        }
255	
256	        // ─────────────────────────────────────────────────────────────────────
257	        // Client SP — OCR_AI_JOB_COUNT (Client DB)
258	        // ─────────────────────────────────────────────────────────────────────
259	        private static DataTable GetClientData(
260	            string connStr,
261	            string flag,
262	            string serverName,
263	            string workingPeriod,
264	            string companyLicense,
265	            string companyName,
266	            string enabledDate,
267	            string disabledDate)
268	        {
269	            try
270	            {
271	                using var conn = new SqlConnection(connStr);
272	                using var cmd = new SqlCommand("OCR_AI_JOB_COUNT", conn)
273	                {
274	                    CommandType = CommandType.StoredProcedure,
275	                    CommandTimeout = 180
276	                };
277	
278	                cmd.Parameters.AddWithValue("@MFLAG", flag);
279	                cmd.Parameters.AddWithValue("@Server_name", serverName);
280	                cmd.Parameters.AddWithValue("@WORKING_PERIOD", workingPeriod);
281	                cmd.Parameters.AddWithValue("@COMPANY_LICENSE", companyLicense);
282	                cmd.Parameters.AddWithValue("@COMPANY_NAME", companyName);
283	                cmd.Parameters.AddWithValue("@ENABLED_DATE", enabledDate);
284	                cmd.Parameters.AddWithValue("@DISABLED_DATE", disabledDate);
285	
286	                var errParam = new SqlParameter("@ERRORMSG",
287	                    System.Data.SqlDbType.NVarChar, -1)
288	                { Direction = ParameterDirection.Output };
289	                cmd.Parameters.Add(errParam);
290	
291	                var adapter = new SqlDataAdapter(cmd);
292	                var ds = new DataSet();
293	                adapter.Fill(ds);
294	
295	                string errMsg = errParam.Value?.ToString();
296	                if (!string.IsNullOrEmpty(errMsg))
297	                    Logger.Warn("Client SP Error [{0}][{1}][{2}]: {3}",
298	                        serverName, companyLicense, flag, errMsg);
299	
300	                // JOB_COUNT uses dynamic SQL → result is in Tables[1] (Tables[0] = PRINT output)
301	                // FORMAT_COUNT is a direct SELECT → result is in Tables[0]
302	                if (flag == "JOB_COUNT")
303	                    return ds.Tables.Count > 1 ? ds.Tables[1] :
304	                           ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
305	
306	                return ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
307	            }
308	            catch (Exception ex)
309	            {
310	                Logger.Error(ex, "GetClientData failed [{0}][{1}][{2}]",
311	                    serverName, companyLicense, flag);
312	                return new DataTable();
313	            }
314	        }
