316	        // ─────────────────────────────────────────────────────────────────────
317	        // Append DataTable to worksheet
318	        // ─────────────────────────────────────────────────────────────────────
319	        private static void AppendDataTable(
320	            IXLWorksheet ws, DataTable table, ref int currentRow)
321	        {
322	            if (table == null || table.Rows.Count == 0) return;
323	
324	            if (currentRow == 1)
325	            {
326	                for (int col = 0; col < table.Columns.Count; col++)
327	                {
328	                    var cell = ws.Cell(currentRow, col + 1);
329	                    cell.Value = table.Columns[col].ColumnName;
330	                    cell.Style.Font.Bold = true;
331	                    cell.Style.Fill.BackgroundColor = XLColor.DarkBlue;
332	                    cell.Style.Font.FontColor = XLColor.White;
333	                    cell.Style.Alignment.Horizontal =
334	                        XLAlignmentHorizontalValues.Center;
335	                }
336	                currentRow++;
337	            }
338	
339	            foreach (DataRow row in table.Rows)
340	            {
341	                for (int col = 0; col < table.Columns.Count; col++)
342	                    ws.Cell(currentRow, col + 1).Value = row[col]?.ToString();
343	
344	                if (currentRow % 2 == 0)
345	                    ws.Range(currentRow, 1, currentRow, table.Columns.Count)
346	                      .Style.Fill.BackgroundColor = XLColor.LightGray;
347	
348	                currentRow++;
349	            }
350	        }
351	
352	        // ─────────────────────────────────────────────────────────────────────
353	        // Style sheet — title, freeze, borders, auto-fit
354	        // ─────────────────────────────────────────────────────────────────────
355	        private static void StyleSheet(
356	            IXLWorksheet ws, string title, int lastDataRow, int colCount)
357	        {
358	            try
359	            {
360	                ws.Row(1).InsertRowsAbove(1);
361	                int usedCols = colCount > 0
362	                    ? colCount
363	                    : ws.LastColumnUsed()?.ColumnNumber() ?? 1;
364	
365	                var titleRange = ws.Range(1, 1, 1, usedCols);
366	                titleRange.Merge();
367	                titleRange.FirstCell().Value = title;
368	                titleRange.Style.Font.Bold = true;
369	                titleRange.Style.Font.FontSize = 14;
370	                titleRange.Style.Alignment.Horizontal =
371	                    XLAlignmentHorizontalValues.Center;
372	                titleRange.Style.Fill.BackgroundColor = XLColor.Navy;
373	                titleRange.Style.Font.FontColor = XLColor.White;
374	
375	                ws.SheetView.FreezeRows(2);
376	
377	                if (ws.RangeUsed() != null)
378	                {
379	                    ws.RangeUsed().Style.Border.OutsideBorder =
380	                        XLBorderStyleValues.Thin;
381	                    ws.RangeUsed().Style.Border.InsideBorder =
382	                        XLBorderStyleValues.Thin;
383	                }
384	
385	                ws.Columns().AdjustToContents();
386	            }
387	            catch (Exception ex)
388	            {
389	                Logger.Warn("StyleSheet failed for {0}: {1}", ws.Name, ex.Message);
390	            }
391	        }
392	
393	        // ─────────────────────────────────────────────────────────────────────
394	        // Parse dd-MM-yyyy → yyyy-MM-dd
395	        // ─────────────────────────────────────────────────────────────────────
396	        private static string ParseDateToYMD(string dateStr)
397	        {
398	            if (string.IsNullOrWhiteSpace(dateStr)) return "";
399	            try
400	            {
401	                return DateTime.ParseExact(dateStr.Trim(), "dd-MM-yyyy", null)
402	                               .ToString("yyyy-MM-dd");
403	            }
404	            catch
405	            {
406	                Logger.Warn("Could not parse date: {0}", dateStr);
407	                return dateStr;
408	            }
409	        }
410	
411	        // ─────────────────────────────────────────────────────────────────────
412	        // Send email with Excel attachment
413	        // ─────────────────────────────────────────────────────────────────────
414	        private static async Task SendEmailWithAttachment(string filePath)
415	        {
416	            try
417	            {
418	                Logger.Info("Sending email...");
419	
420	                // ── Yesterday's date for subject and body ─────────────────────
421	                string reportDate = DateTime.Now.AddDays(-1).ToString("dd-MM-yyyy");
422	
423	                string subject = _smtpSettings.Subject.Replace("{Date}", reportDate);
424	                string htmlBody = _smtpSettings.Body.Replace("{Date}", reportDate);
425	
426	                using var mail = new MailMessage
427	                {
428	                    From = new MailAddress(
429	                                     _smtpSettings.FromEmail,
430	                                     _smtpSettings.Mail_header),
431	                    Subject = subject,
432	                    IsBodyHtml = true
433	                };
434	
435	                // ── Logo (inline) if present ──────────────────────────────────
436	                string logoPath = Path.Combine(
437	                    AppContext.BaseDirectory, "Assets", "Company_Logo.png");
438	
439	                if (File.Exists(logoPath))
440	                {
441	                    var htmlView = AlternateView.CreateAlternateViewFromString(
442	                        htmlBody, null, "text/html");
443	                    var logoRes = new LinkedResource(logoPath, "image/png")
444	                    { ContentId = "companylogo" };
445	                    htmlView.LinkedResources.Add(logoRes);
446	                    mail.AlternateViews.Add(htmlView);
447	                }
448	                else
449	                {
450	                    Logger.Warn("Logo not found at {0}; sending without logo", logoPath);
451	                    mail.Body = htmlBody;
452	                }
453	
454	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
455	                    mail.To.Add(to.Trim());
456	
457	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
458	                    mail.CC.Add(cc.Trim());
459	
460	                using (var fs = new FileStream(
461	                    filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
462	                {
463	                    mail.Attachments.Add(new Attachment(fs, Path.GetFileName(filePath)));
464	
465	                    using var smtp = new SmtpClient(
466	                        _smtpSettings.Host, _smtpSettings.SmtpPort)
467	                    {
468	                        Credentials = new NetworkCredential(
469	                            _smtpSettings.username, _smtpSettings.password),
470	                        EnableSsl = _smtpSettings.enableSsl
471	                    };
472	                    await smtp.SendMailAsync(mail);
473	                }
474	
475	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
476	
477	                if (File.Exists(filePath))
478	                {
479	                    File.Delete(filePath);
480	                    Logger.Info("Deleted report: {0}", filePath);
481	                }
482	            }
483	            catch (Exception ex)
484	            {
485	                Logger.Error(ex, "Email send failed");
486	            }
487	        }
488	    }
489	}

