using ClosedXML.Excel;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using NLog;
using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Mail;
using System.Threading.Tasks;

namespace DSRAutoMailScheduler
{
    class Program
    {
        private static readonly Logger Logger = LogManager.GetCurrentClassLogger();
        private static SmtpSettings _smtpSettings;
        private static Dictionary<string, ServerInfo> _serverDict;
        private static string ReportFolder;
        private static string fileName;
        private static string savePath;

        public class SmtpSettings
        {
            public string Mail_header { get; set; }
            public string Host { get; set; }
            public string username { get; set; }
            public string password { get; set; }
            public int SmtpPort { get; set; }
            public bool enableSsl { get; set; }
            public string FromEmail { get; set; }
            public string[] ToEmails { get; set; }
            public string[] CCEmails { get; set; }
            public string Subject { get; set; }
            public string Body { get; set; }
        }

        public class ServerInfo
        {
            public string Ip { get; set; }
            public string AdminUser { get; set; }
            public string AdminPassword { get; set; }
        }

        public class RowPointers
        {
            public int ClientRow = 1;  // Sheet 1
            public int JobRow = 1;  // Sheet 2
            public int FormatRow = 1;  // Sheet 3
        }

        static async Task Main(string[] args)
        {
            bool isDryRun = args.Any(a =>
                string.Equals(a, "--dry-run", StringComparison.OrdinalIgnoreCase));

            try
            {
                RowPointers rows = new RowPointers();

                var builder = new ConfigurationBuilder()
                    .SetBasePath(AppContext.BaseDirectory)
                    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);

                IConfiguration config = builder.Build();
                _smtpSettings = config.GetSection("SmtpSettings").Get<SmtpSettings>();
                _serverDict = config.GetSection("server_ip_list")
                                      .Get<Dictionary<string, ServerInfo>>();
                ReportFolder = config.GetSection("ReportSettings:ReportFolder").Value;

                if (!Directory.Exists(ReportFolder))
                    Directory.CreateDirectory(ReportFolder);

                using var workbook = new XLWorkbook();
                {
                    var wsClient = workbook.Worksheets.Add("AI_OCR ENABLED CLIENT LIST");
                    var wsJob = workbook.Worksheets.Add("AI_OCR TOTAL JOB COUNT");
                    var wsFormat = workbook.Worksheets.Add("AI_OCR TOTAL FORMAT DETAILS");

                    foreach (var kvp in _serverDict)
                    {
                        string serverName = kvp.Key;
                        ServerInfo info = kvp.Value;

                        Logger.Info("Processing server {0} ({1})", serverName, info.Ip);

                        string connString =
                            $"Server={info.Ip};database=ADMIN_IMPEX;" +
                            $"uid={info.AdminUser};pwd={info.AdminPassword};" +
                            $"TrustServerCertificate=True;";

                        await GetOcrDataList(
                            connString, wsClient, wsJob, wsFormat, serverName, rows);
                    }

                    // ── Style sheets ──────────────────────────────────────────
                    StyleSheet(wsClient, "AI_OCR ENABLED CLIENT LIST", rows.ClientRow - 1, 7);
                    StyleSheet(wsJob, "AI_OCR TOTAL JOB COUNT", rows.JobRow - 1, -1);
                    StyleSheet(wsFormat, "AI_OCR TOTAL FORMAT DETAILS", rows.FormatRow - 1, 13);

                    fileName = $"AI_OCR_Report_{DateTime.Now:yyyyMMdd_HHmm}.xlsx";
                    savePath = Path.Combine(ReportFolder, fileName);
                    workbook.SaveAs(savePath);
                    Logger.Info("Excel saved: {0}", savePath);
                }

                if (isDryRun)
                {
                    Logger.Info("Dry run — email skipped. File at: {0}", savePath);
                    return;
                }

                await SendEmailWithAttachment(savePath);

                if (File.Exists(savePath))
                {
                    File.Delete(savePath);
                    Logger.Info("Deleted report after email: {0}", fileName);
                }
            }
            catch (Exception ex)
            {
                Logger.Error(ex, "Error in Main");
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // Main data fetch per server
        // ─────────────────────────────────────────────────────────────────────
        private static async Task GetOcrDataList(
            string connString,
            IXLWorksheet wsClient,
            IXLWorksheet wsJob,
            IXLWorksheet wsFormat,
            string serverName,
            RowPointers rows)
        {
            await Task.Run(() =>
            {
                // ── Step 1: Admin SP ──────────────────────────────────────────
                DataSet adminData;
                try
                {
                    adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
                }
                catch (Exception ex)
                {
                    Logger.Error(ex, "Admin SP failed for server {0}", serverName);
                    return;
                }

                if (adminData == null || adminData.Tables.Count < 2)
                {
                    Logger.Warn("Server {0}: No data from admin SP", serverName);
                    return;
                }

                DataTable clientList = adminData.Tables[0]; // → Sheet 1
                DataTable serverList = adminData.Tables[1]; // connection details

                Logger.Info("Server {0}: Clients={1}, DB rows={2}",
                    serverName, clientList.Rows.Count, serverList.Rows.Count);

                // ── Sheet 1 ───────────────────────────────────────────────────
                AppendDataTable(wsClient, clientList, ref rows.ClientRow);

                // ── Step 2: Deduplicate by COMPANY_LICENSE ────────────────────
                // Admin SP returns one row per IMP/EXP per company.
                // We only need one DB connection per company for client SP calls.
                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var uniqueServers = serverList.AsEnumerable()
                    .Where(r => seen.Add(r["COMPANY_LICENSE"].ToString().Trim()))
                    .ToList();

                Logger.Info("Server {0}: Unique companies after dedup = {1}",
                    serverName, uniqueServers.Count);

                foreach (DataRow server in uniqueServers)
                {
                    string workingPeriod = server["WORKING_PERIOD"].ToString();
                    string companyLicense = server["COMPANY_LICENSE"].ToString();
                    string companyName = server["COMPANY_NAME"].ToString();
                    string clientConn = server["CON_STRING"].ToString();

