            public int JobRow = 1;  // Sheet 2
            public int FormatRow = 1;  // Sheet 3
        }

        static async Task Main(string[] args)
        {
            bool isDryRun = args.Any(a =>
                string.Equals(a, "--dry-run", StringComparison.OrdinalIgnoreCase));

