                    Directory.CreateDirectory(ReportFolder);

                using var workbook = new XLWorkbook();
                {
                    var wsClient = workbook.Worksheets.Add("AI_OCR ENABLED CLIENT LIST");
                    var wsJob = workbook.Worksheets.Add("AI_OCR TOTAL JOB COUNT");
